104	        throws IOException {
105	    this.conf = conf;
106	
107	    Configuration confForInfoServer = new Configuration(conf);
108	    confForInfoServer.setInt(HttpServer2.HTTP_MAX_THREADS_KEY,
109	        HTTP_MAX_THREADS);
110	    confForInfoServer.setInt(HttpServer2.HTTP_SELECTOR_COUNT_KEY,
111	        HTTP_SELECTOR_THREADS);
112	    confForInfoServer.setInt(HttpServer2.HTTP_ACCEPTOR_COUNT_KEY,
113	        HTTP_ACCEPTOR_THREADS);
114	    int proxyPort =
115	        confForInfoServer.getInt(DFS_DATANODE_HTTP_INTERNAL_PROXY_PORT, 0);
116	    HttpServer2.Builder builder = new HttpServer2.Builder()
117	        .setName("datanode")
118	        .setConf(confForInfoServer)
119	        .setACL(new AccessControlList(conf.get(DFS_ADMIN, " ")))
120	        .hostName(getHostnameForSpnegoPrincipal(confForInfoServer))
121	        .addEndpoint(URI.create("http://localhost:" + proxyPort))
122	        .setFindPort(true);
123	
124	    final boolean xFrameEnabled = conf.getBoolean(
125	        DFSConfigKeys.DFS_XFRAME_OPTION_ENABLED,
126	        DFSConfigKeys.DFS_XFRAME_OPTION_ENABLED_DEFAULT);
127	
128	    final String xFrameOptionValue = conf.getTrimmed(
129	        DFSConfigKeys.DFS_XFRAME_OPTION_VALUE,
130	        DFSConfigKeys.DFS_XFRAME_OPTION_VALUE_DEFAULT);
131	
132	    builder.configureXFrame(xFrameEnabled).setXFrameOption(xFrameOptionValue);
133	
134	    this.infoServer = builder.build();
135	
136	    this.infoServer.setAttribute(HttpServer2.CONF_CONTEXT_ATTRIBUTE, conf);
137	    this.infoServer.setAttribute("datanode", datanode);
138	    this.infoServer.setAttribute(JspHelper.CURRENT_CONF, conf);
139	    this.infoServer.addServlet(null, "/blockScannerReport",
140	        BlockScanner.Servlet.class);
141	    DataNodeUGIProvider.init(conf);
142	    this.infoServer.start();
143	    final InetSocketAddress jettyAddr = infoServer.getConnectorAddress(0);
144	
145	    this.confForCreate = new Configuration(conf);
146	    confForCreate.set(FsPermission.UMASK_LABEL, "000");
147	
148	    this.bossGroup = new NioEventLoopGroup();
149	    this.workerGroup = new NioEventLoopGroup();
150	    this.externalHttpChannel = externalHttpChannel;
151	    HttpConfig.Policy policy = DFSUtil.getHttpPolicy(conf);
152	    final ChannelHandler[] handlers = getFilterHandlers(conf);
153	
154	    if (policy.isHttpEnabled()) {
155	      this.httpServer = new ServerBootstrap().group(bossGroup, workerGroup)
156	            .childHandler(new ChannelInitializer<SocketChannel>() {
157	              @Override
158	              protected void initChannel(SocketChannel ch) throws Exception {
159	                ChannelPipeline p = ch.pipeline();
160	                p.addLast(new HttpRequestDecoder(),
161	                    new HttpResponseEncoder());
162	                if (handlers != null) {
163	                  for (ChannelHandler c : handlers) {
164	                    p.addLast(c);
165	                  }
166	                }
167	                p.addLast(
168	                    new ChunkedWriteHandler(),
169	                    new URLDispatcher(jettyAddr, conf, confForCreate));
170	              }
171	            });
172	
173	      this.httpServer.childOption(
174	          ChannelOption.WRITE_BUFFER_HIGH_WATER_MARK,
175	          conf.getInt(
176	              DFSConfigKeys.DFS_WEBHDFS_NETTY_HIGH_WATERMARK,
177	              DFSConfigKeys.DFS_WEBHDFS_NETTY_HIGH_WATERMARK_DEFAULT));
178	      this.httpServer.childOption(
179	          ChannelOption.WRITE_BUFFER_LOW_WATER_MARK,
180	          conf.getInt(
181	              DFSConfigKeys.DFS_WEBHDFS_NETTY_LOW_WATERMARK,
182	              DFSConfigKeys.DFS_WEBHDFS_NETTY_LOW_WATERMARK_DEFAULT));
183	
184	      if (externalHttpChannel == null) {
185	        httpServer.channel(NioServerSocketChannel.class);
186	      } else {
187	        httpServer.channelFactory(new ChannelFactory<NioServerSocketChannel>() {
188	          @Override
189	          public NioServerSocketChannel newChannel() {
190	            return new NioServerSocketChannel(externalHttpChannel) {
